import{d as g,C as n,o as s,c as h,E as a,a3 as i}from"./chunks/framework.D4-ViStF.js";const c=JSON.parse('{"title":"观卦","description":"第二十卦·风地观——风行地上，省方观民设教。","frontmatter":{"title":"观卦","description":"第二十卦·风地观——风行地上，省方观民设教。","category":"hexagram","aliases":["观","风地观"],"source":["《周易》"]},"headers":[],"relativePath":"yijing/hexagrams/hexagram-20.md","filePath":"yijing/hexagrams/hexagram-20.md","lastUpdated":1787730063000}'),u={name:"yijing/hexagrams/hexagram-20.md"},x=g({...u,setup(p){const r=[{id:"tongguan",term:"童观",pinyin:"tóng guān",meaning:"孩童式的观看，懵懂、认知有限。认知决定角度，角度决定所见。"},{id:"kuiguan",term:"窥观",pinyin:"kuī guān",meaning:"从缝隙中看，开始接触认知之外的事物。不是全貌，但已突破童观的封闭。"},{id:"guanwosheng",term:"观我生",pinyin:"guān wǒ shēng",meaning:"观察自己的生——自己的认知与行为。六三与九五同辞，境界不同。"},{id:"guanguozhiguang",term:"观国之光",pinyin:"guān guó zhī guāng",meaning:"观察国家的光彩，看见文明、趋势与更大的格局。"},{id:"liyongbin",term:"利用宾于王",pinyin:"lì yòng bīn yú wáng",meaning:"以宾客之礼、不卑不亢地走向那道光。不是去争、去证明，是有备而来。"},{id:"guanqisheng",term:"观其生",pinyin:"guān qí shēng",meaning:"观生命本身。「其」字囊括一切，连观察者本身也被观察了。"},{id:"xiaorendao",term:"小人道",pinyin:"xiǎo rén dào",meaning:"小人之道。童观是小人的常态，认知未开。"},{id:"yikechou",term:"亦可丑",pinyin:"yì kě chǒu",meaning:"也是可羞的。窥观而守正，对女子尚可，但终究不是观的正道。"},{id:"weishidao",term:"未失道",pinyin:"wèi shī dào",meaning:"没有失去正道。进退未定，但尚未偏离道。"},{id:"shangbin",term:"尚宾",pinyin:"shàng bīn",meaning:"崇尚宾客之礼。观国之光，尚宾也。"},{id:"guanmin",term:"观民",pinyin:"guān mín",meaning:"观察民情。观我生，就是观民——反观自己，也就照见了众人。"},{id:"zhiweiping",term:"志未平",pinyin:"zhì wèi píng",meaning:"志向尚未平定。观其生，志未平也——「观」没有尽头，永远在路上。"}],e=[{position:"初六",type:"yin",text:"童观，小人无咎，君子吝。",xiang:"初六童观，小人道也。",textModern:"孩童式的观看，懵懂、认知有限；认知决定角度，角度决定所见。对小人无咎（认知本就如此），对君子则是不足。",xiangModern:"童观是小人之道——停留在懵懂的观看，是认知未开的状态。"},{position:"六二",type:"yin",text:"窥观，利女贞。",xiang:"窥观女贞，亦可丑也。",textModern:"从缝隙中看，开始接触认知之外的事物；不是全貌，但已突破童观的封闭。以柔顺、守正的姿态持续观察。",xiangModern:"从缝隙窥看而守正，对女子尚且可以，但终究是可羞的——不是观的正道。"},{position:"六三",type:"yin",text:"观我生，进退。",xiang:"观我生进退，未失道也。",textModern:"第一次「观我生」——新旧认知碰撞，可以退回去，也可以接受新的；进退未定，是真实的摇摆，打破固有认知的关口就在这里。",xiangModern:"观我生而进退，尚未失去正道——摇摆本身不可怕，只要不偏离道。"},{position:"六四",type:"yin",text:"观国之光，利用宾于王。",xiang:"观国之光，尚宾也。",textModern:"因为自己不同了，开始以新认知观察自身以外的事物；国之光浮现——看见了文明、趋势、更大的格局。以宾客之礼、不卑不亢地走向那道光。",xiangModern:"观国之光，在于崇尚宾客之礼——不是去争、去证明，是有备而来。"},{position:"九五",type:"yang",text:"观我生，君子无咎。",xiang:"观我生，观民也。",textModern:"第二次「观我生」，与六三同辞，境界全然不同——六三摇摆，九五有定力、观而不乱。君子之位，持续自观，不因外境动摇，走完了一生（不是长度，是完整度）。",xiangModern:"观我生，就是观民——反观自己，也就照见了众人。"},{position:"上九",type:"yang",text:"观其生，君子无咎。",xiang:"观其生，志未平也。",textModern:"一字之差，观我生 → 观其生。不再是「看意义上的我」，而是放下自我、观生命本身——英雄、小人、市井、圣贤，全在「其」中，连观察者本身也被观察了。",xiangModern:"观其生，而志向尚未平定——因为「观」没有尽头，永远在路上。"}];return(m,t)=>{const o=n("DaoHexagramViewer"),l=n("DaoHexagramYaoCards"),d=n("DaoKeywordCards");return s(),h("div",null,[a(o,{name:"观",fullName:"风地观",upper:"☴",lower:"☷",guaCi:"观，盥而不荐，有孚颙若。",pinyin:["guān"],element:"木",direction:"东南",insight:"风行地上，遍观万物；盥而不荐，有孚颙若，观在每一刻的诚实。",guaSlug:"20fengdiguan",lines:e}),t[0]||(t[0]=i('<h2 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to &quot;象传&quot;">​</a></h2><p>风行地上，观。先王以省方观民设教。</p><p>上巽为风、下坤为地，风行地上、遍观万物，是「观」之象。先王由此悟到：要<strong>省察四方、观察民情、设立教化</strong>——先观而后教，观是教的前提。</p><h2 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to &quot;彖传&quot;">​</a></h2><p>大观在上，顺而巽，中正以观天下。观，盥而不荐，有孚颙若，下观而化也。观天之神道，而四时不忒。圣人以神道设教，而天下服矣。</p><p>逐句释义：</p><ul><li><strong>大观在上，顺而巽，中正以观天下</strong> —— 大观在上（九五、上九居上），下坤顺、上巽入，以中正之道观天下。</li><li><strong>观，盥而不荐，有孚颙若，下观而化也</strong> —— 「盥而不荐」，诚信庄重，下面的人观之而感化。</li><li><strong>观天之神道，而四时不忒</strong> —— 观察天地的神妙之道，四季运行没有差错。</li><li><strong>圣人以神道设教，而天下服矣</strong> —— 圣人以神道设教，天下就顺服了。</li></ul><blockquote><p><strong>盥而不荐，有孚颙若</strong>：盥是祭祀前的洗手净心，荐是正式献祭；颙若是严肃凝重的样子。核心在于——状态不是在「表演」那一刻才有，在做这件事之前，内心已经是这个状态了。这是中孚的根：不是做给别人看的，是本来就在那里的。</p></blockquote><h2 id="六爻" tabindex="-1">六爻 <a class="header-anchor" href="#六爻" aria-label="Permalink to &quot;六爻&quot;">​</a></h2>',9)),a(l,{element:"木",guaSlug:"20fengdiguan",glossary:r,items:e}),t[1]||(t[1]=i('<h2 id="六爻详解" tabindex="-1">六爻详解 <a class="header-anchor" href="#六爻详解" aria-label="Permalink to &quot;六爻详解&quot;">​</a></h2><h3 id="初六-·-童观-小人无咎-君子吝" tabindex="-1">初六 · 童观，小人无咎，君子吝 <a class="header-anchor" href="#初六-·-童观-小人无咎-君子吝" aria-label="Permalink to &quot;初六 · 童观，小人无咎，君子吝&quot;">​</a></h3><ul><li><strong>童观</strong>：孩童式的观看，懵懂，认知有限</li><li>认知决定角度，角度决定所见</li><li>对小人无咎（认知本就如此），对君子则是不足</li></ul><blockquote><p>认知决定角度。</p></blockquote><h3 id="六二-·-窥观-利女贞" tabindex="-1">六二 · 窥观，利女贞 <a class="header-anchor" href="#六二-·-窥观-利女贞" aria-label="Permalink to &quot;六二 · 窥观，利女贞&quot;">​</a></h3><ul><li><strong>窥观</strong>：从缝隙中看，开始接触认知之外的事物</li><li>不是全貌，但已经突破了童观的封闭</li><li><strong>利女贞</strong>：以柔顺、守正的姿态持续观察</li></ul><blockquote><p>开始接触认知之外。</p></blockquote><h3 id="六三-·-观我生-进退" tabindex="-1">六三 · 观我生，进退 <a class="header-anchor" href="#六三-·-观我生-进退" aria-label="Permalink to &quot;六三 · 观我生，进退&quot;">​</a></h3><ul><li>第一次出现「观我生」</li><li><strong>碰撞</strong>：新旧认知相遇，可以选择退回去，也可以选择接受新的</li><li>进退未定，是真实的摇摆——打破固有认知的关口就在这里</li></ul><blockquote><p>碰撞，可进可退。</p></blockquote><h3 id="六四-·-观国之光-利用宾于王" tabindex="-1">六四 · 观国之光，利用宾于王 <a class="header-anchor" href="#六四-·-观国之光-利用宾于王" aria-label="Permalink to &quot;六四 · 观国之光，利用宾于王&quot;">​</a></h3><ul><li>因为自己不同了，开始以新的认知观察自身以外的事物</li><li><strong>国之光浮现</strong>：看见了文明、趋势、更大的格局</li><li><strong>利用宾于王</strong>：以宾客之礼，带着所见，踏实走向那道光——不是去争、不是去证明，是有备而来、不卑不亢</li></ul><p><strong>与小畜六四的关系</strong>：</p><table tabindex="0"><thead><tr><th>爻</th><th>内容</th><th>方向</th></tr></thead><tbody><tr><td>小畜六四</td><td>有孚，血去惕出，无咎</td><td>诚实向内守</td></tr><tr><td>观六四</td><td>观国之光，利宾于王</td><td>诚实向外观</td></tr></tbody></table><p>先有小畜六四的功课（内在诚实，恐惧散去），才能到观六四的境界（内在清明，看见外面的光）。</p><blockquote><p>向外观，感受到光。</p></blockquote><h3 id="九五-·-观我生-君子无咎" tabindex="-1">九五 · 观我生，君子无咎 <a class="header-anchor" href="#九五-·-观我生-君子无咎" aria-label="Permalink to &quot;九五 · 观我生，君子无咎&quot;">​</a></h3><ul><li>第二次「观我生」，与六三同辞，境界全然不同</li><li>六三的观我生：摇摆，进退未定</li><li>九五的观我生：有定力，观而不乱，无咎</li><li>君子之位，持续自观，不因外境动摇；走完了一生——不是长度，是完整度</li></ul><blockquote><p>有定力的自观。</p></blockquote><h3 id="上九-·-观其生-君子无咎" tabindex="-1">上九 · 观其生，君子无咎 <a class="header-anchor" href="#上九-·-观其生-君子无咎" aria-label="Permalink to &quot;上九 · 观其生，君子无咎&quot;">​</a></h3><ul><li>一字之差：观我生 → 观其生</li><li>不再是「看意义上的我」，而是一种压缩、微观</li><li><strong>「其」字囊括一切</strong>：英雄、小人、市井、圣贤，全在「其」中；连观察者本身也被观察了</li></ul><p><strong>庄子的呼应</strong>：「道在蝼蚁，在稊稗，在瓦甓，在屎溺。」——道无处不在，不是道降低了，是观的眼睛打开了。</p><blockquote><p>连「我」也放下，观生命本身。</p></blockquote><h2 id="【原典层】字词释义" tabindex="-1">【原典层】字词释义 <a class="header-anchor" href="#【原典层】字词释义" aria-label="Permalink to &quot;【原典层】字词释义&quot;">​</a></h2>',24)),a(d,{title:"字词释义",items:[{term:"观",pinyin:["guān"],meaning:"观看、观察。风行地上，遍观万物。"},{term:"盥",pinyin:["guàn"],meaning:"祭祀前的洗手净心。"},{term:"荐",pinyin:["jiàn"],meaning:"正式献祭。「盥而不荐」：状态在献祭之前就已经在了。"},{term:"颙若",pinyin:["yóng","ruò"],meaning:"严肃凝重的样子。"},{term:"童观",pinyin:["tóng","guān"],meaning:"孩童式的观看，懵懂、认知有限。"},{term:"窥观",pinyin:["kuī","guān"],meaning:"从缝隙中看，接触认知之外。"},{term:"观我生",pinyin:["guān","wǒ","shēng"],meaning:"观察自己的生——认知与行为。"},{term:"观国之光",pinyin:["guān","guó","zhī","guāng"],meaning:"观察国家的光彩、文明与格局。"},{term:"观其生",pinyin:["guān","qí","shēng"],meaning:"观生命本身，连观察者也被观察。"},{term:"宾于王",pinyin:["bīn","yú","wáng"],meaning:"以宾客之礼事王，不卑不亢。"}]}),t[2]||(t[2]=i('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一卦在说什么" tabindex="-1">象：这一卦在说什么 <a class="header-anchor" href="#象-这一卦在说什么" aria-label="Permalink to &quot;象：这一卦在说什么&quot;">​</a></h3><p>观卦讲的是<strong>观看与观察</strong>。上巽（风）下坤（地），风行地上，遍观万物。</p><p>卦辞「盥而不荐，有孚颙若」点明：状态不是在「表演」那一刻才有，在做这件事之前，内心已经是这个状态了——观不是做给别人看的，是本来就在那里的。</p><h3 id="理-为什么这一卦重要" tabindex="-1">理：为什么这一卦重要 <a class="header-anchor" href="#理-为什么这一卦重要" aria-label="Permalink to &quot;理：为什么这一卦重要&quot;">​</a></h3><p>观是一条完整的路：懵懂（童观）→ 局限（窥观）→ 碰撞（观我生进退）→ 看见光（观国之光）→ 有定力（观我生无咎）→ 超越自我（观其生）。</p><p>观不是一次性的到达，是每一刻的诚实。</p><h3 id="用-今天如何应用" tabindex="-1">用：今天如何应用 <a class="header-anchor" href="#用-今天如何应用" aria-label="Permalink to &quot;用：今天如何应用&quot;">​</a></h3><ol><li>认知决定角度，角度决定所见（初六童观）</li><li>开始接触认知之外（六二窥观）</li><li>在碰撞中摇摆，但不失道（六三进退）</li><li>向外观，看见更大的格局（六四观国之光）</li><li>有定力的自观，观而不乱（九五）</li><li>连「我」也放下，观生命本身（上九）</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>全卦脉络：</p><table tabindex="0"><thead><tr><th>爻位</th><th>爻辞</th><th>状态</th></tr></thead><tbody><tr><td>初六</td><td>童观，小人无咎，君子吝</td><td>懵懂地看，认知决定角度</td></tr><tr><td>六二</td><td>窥观，利女贞</td><td>局限地看，接触认知之外</td></tr><tr><td>六三</td><td>观我生，进退</td><td>碰撞、摇摆，可进可退</td></tr><tr><td>六四</td><td>观国之光，利用宾于王</td><td>自己变了，看见外面的光</td></tr><tr><td>九五</td><td>观我生，君子无咎</td><td>有定力，走完了一生</td></tr><tr><td>上九</td><td>观其生，君子无咎</td><td>连我也放下，观生命本身</td></tr></tbody></table><p>三个「无咎」的来源：</p><table tabindex="0"><thead><tr><th>卦爻</th><th>无咎的来源</th></tr></thead><tbody><tr><td>小畜六四</td><td>有孚，诚实守位</td></tr><tr><td>观九五</td><td>观我生，诚实自观</td></tr><tr><td>观上九</td><td>观其生，放下自我</td></tr></tbody></table><p>两个无咎，都不是来自力量，都是来自<strong>诚实</strong>。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><p>中孚的位置：</p><ul><li><strong>根</strong>：中孚（内在诚信不动摇）</li><li><strong>眼睛</strong>：观六四（已感受到国之光）</li><li><strong>脚下</strong>：一步一步，踏实走</li><li><strong>方向</strong>：利宾于王</li></ul><p><strong>此刻的感悟</strong>：是此刻观到了。希望能保持谦逊和警醒，这样观的状态才会保持。盥而不荐，有孚颙若——状态从一开始就在，不是表演，是本来就在。观，不是一次性的到达，是每一刻的诚实。</p><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>相关卦象：临（第十九卦）、小畜（第九卦）</li><li>临与观：俯临与仰观，是一对——你临，也要能观</li><li>小畜与观：小畜六四（诚实向内守）→ 观六四（诚实向外观）</li><li>相关专题：<a href="/Dao/topics/yin-yang">阴阳</a>、<a href="/Dao/topics/xiang-shu-li">象数理</a></li></ul>',21))])}}});export{c as __pageData,x as default};
